// src/routes/Routers.js

import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';

import Home from '../../pages/Home';
import About from '../../pages/About';
import Register from '../../pages/Register';
import GenerateTT from '../../pages/GenerateTT';
import OneHLPage from '../../pages/OneHL';
import TwoHLPage from '../../pages/TwoHL';
import ThreeHLPage from '../../pages/ThreeHL';
import FourHLPage from '../../pages/fourHL';
import FiveHLPage from '../../pages/fiveHL';
import AdminPanel from '../../pages/AdminPanel';

import ProtectedRoute from '../ProtectedRoutes/ProtectedRoutes';

const Routers = () => {
  return (
    <Routes>

      {/* ================= PUBLIC ROUTES ================= */}
      <Route path="/" element={<Home />} />
      <Route path="/register" element={<Register />} />

      {/* ================= PROTECTED ROUTES ================= */}
      <Route
        path="/about"
        element={
          <ProtectedRoute>
            <About />
          </ProtectedRoute>
        }
      />

      <Route
        path="/timetable"
        element={
          <ProtectedRoute>
            <GenerateTT />
          </ProtectedRoute>
        }
      />

      <Route
        path="/oneHL"
        element={
          <ProtectedRoute>
            <OneHLPage />
          </ProtectedRoute>
        }
      />

      <Route
        path="/twoHL"
        element={
          <ProtectedRoute>
            <TwoHLPage />
          </ProtectedRoute>
        }
      />

      <Route
        path="/threeHL"
        element={
          <ProtectedRoute>
            <ThreeHLPage />
          </ProtectedRoute>
        }
      />

      <Route
        path="/fourHL"
        element={
          <ProtectedRoute>
            <FourHLPage />
          </ProtectedRoute>
        }
      />

      <Route
        path="/fiveHL"
        element={
          <ProtectedRoute>
            <FiveHLPage />
          </ProtectedRoute>
        }
      />

      <Route
        path="/adminpanel"
        element={
          <ProtectedRoute>
            <AdminPanel />
          </ProtectedRoute>
        }
      />

      {/* ================= FALLBACK ================= */}
      <Route path="*" element={<Navigate to="/" replace />} />

    </Routes>
  );
};

export default Routers;
